set -e; u='tester'; h=$(getent passwd "$u" | cut -d: -f6); [ -n "$h" ]; mkdir -p "$h/.ssh"; chmod 700 "$h/.ssh"; f="$h/.ssh/authorized_keys"; cat > "$f.edit"; [ -f "$f" ] || touch "$f"; awk 'function t(x) { sub(/^[ \t]+/, "", x); sub(/[ \t\r]+$/, "", x); return x } FILENAME == ARGV[1] { k = t(substr($0, 3)); if (k == "") next; if (substr($0, 1, 2) == "- ") del[k] = 1; else if (substr($0, 1, 2) == "+ ") add[++n] = k; next } { k = t($0); if (k in del) { r++; next } if (k != "") have[k] = 1; print } END { for (i = 1; i <= n; i++) if (!(add[i] in have) && !(add[i] in del)) { print add[i]; have[add[i]] = 1; a++ } printf "added=%d removed=%d\n", a, r > "/dev/stderr" }' "$f.edit" "$f" > "$f.tmp" 2> "$f.count"; rm -f "$f.edit"; chmod 600 "$f.tmp"; mv -f "$f.tmp" "$f"; chown -R "$u": "$h/.ssh"; echo "OK $(cat "$f.count")"; rm -f "$f.count"
